import{z as n,x as o,o as A,c as s,q as e,j as l,D as E,d as B,s as r,S as i}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"多后端移植","description":"","frontmatter":{"title":"多后端移植","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/ak-multi-backend.md","filePath":"llm/ak-multi-backend.md","lastUpdated":1791413859000}'),p={name:"llm/ak-multi-backend.md"};function m(d,a,h,C,F,D){const t=o("Mermaid");return A(),s("div",null,[a[2]||(a[2]=e('<h1 id="多后端移植" tabindex="-1">多后端移植 <a class="header-anchor" href="#多后端移植" aria-label="Permalink to &quot;多后端移植&quot;">​</a></h1><div class="epigraph"><p>算法是一份，内核是很多份；移植的真正工件不是翻译代码，而是先把不变式与验收口径钉死。</p><footer>—— 据 CUTLASS 与 FlashInfer 文档、Tillet et al., 2019（Triton）整理</footer></div><p><a href="/llm/ak-autotuning">上一课</a>把配置表立成合同。本课处理换硬件：多后端移植。同一份 tiling 加 online softmax，在 A100、Hopper、AMD 与国产加速器上是几套不同的代码；本课讲分层、路由与跨后端的验收——移植做错，错误通常不在「搬不动」，而在「搬过去以后谁也不确定它对不对」。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>两条路都通向坏结局。把 CUDA 源码当规范逐行翻译：warp shuffle、异步拷贝、TMA、矩阵指令这些原语在别的后端要么不存在要么语义不同，翻译半途而废；只维护一份「最慢公分母」的实现（比如纯 Triton 版）：在每家硬件上都拿不到该拿的份额，移植成了降级。更隐蔽的是数值：各后端的默认归约顺序、累加宽度、数学库不同，同一容差下结果漂移——上游把它当 bug 报，下游把它当正常吞，两边都没有口径。缺口是：算法层、调度层、验收层分开，各自有各自的合同。</p><p><span class="marginnote">术语翻译：「后端」就是同一份算法在一种硬件上的具体实现——CUDA 后端跑 NVIDIA 卡，ROCm 后端跑 AMD 卡。算法只有一份（切块、在线 softmax），实现却每家一份，因为每家卡的「方言」：专用指令、缓存大小、搬运方式都不一样。</span></p><h3 id="分层的依据是「什么随硬件变」" tabindex="-1">分层的依据是「什么随硬件变」 <a class="header-anchor" href="#分层的依据是「什么随硬件变」" aria-label="Permalink to &quot;分层的依据是「什么随硬件变」&quot;">​</a></h3><p>随硬件变的是原语与额度：smem 大小、异步搬运、矩阵指令、流水深度。不随硬件变的是算法：块结构、在线 softmax 的统计量更新、掩码语义、变长与分页接口。把变的和不变的拆开，移植就有了分工。</p>',8)),(A(),l(i,null,{default:E(()=>[r(t,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20LR%0A%20%20S%5B%22%E4%B8%8D%E9%9A%8F%E7%A1%AC%E4%BB%B6%E5%8F%98%3A%20%E7%AE%97%E6%B3%95%E8%A7%84%E8%8C%83%22%5D%20--%3E%20A1%5B%22%E5%9D%97%E7%BB%93%E6%9E%84%22%5D%0A%20%20S%20--%3E%20A2%5B%22%E5%9C%A8%E7%BA%BF%20softmax%20%E7%BB%9F%E8%AE%A1%E9%87%8F%E6%9B%B4%E6%96%B0%22%5D%0A%20%20S%20--%3E%20A3%5B%22%E6%8E%A9%E7%A0%81%20%2F%20%E5%8F%98%E9%95%BF%20%2F%20%E5%88%86%E9%A1%B5%E6%8E%A5%E5%8F%A3%22%5D%0A%20%20H%5B%22%E9%9A%8F%E7%A1%AC%E4%BB%B6%E5%8F%98%3A%20%E8%B0%83%E5%BA%A6%E5%AE%9E%E7%8E%B0%22%5D%20--%3E%20B1%5B%22smem%20%E9%A2%9D%E5%BA%A6%E4%B8%8E%E5%8F%8C%E7%BC%93%E5%86%B2%22%5D%0A%20%20H%20--%3E%20B2%5B%22TMA%20%2F%20%E5%BC%82%E6%AD%A5%E6%8B%B7%E8%B4%9D%20%2F%20%E7%9F%A9%E9%98%B5%E6%8C%87%E4%BB%A4%22%5D%0A%20%20A1%20--%3E%20C%5B%22%E6%AF%8F%E5%90%8E%E7%AB%AF%E5%90%84%E8%87%AA%E9%87%8D%E6%8E%92%2C%20%E8%BF%87%E5%90%8C%E4%B8%80%E5%A5%97%E9%AA%8C%E6%94%B6%22%5D%0A%20%20A2%20--%3E%20C%0A%20%20A3%20--%3E%20C%0A%20%20B1%20--%3E%20C%0A%20%20B2%20--%3E%20C%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[B(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e('<h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>三层移植法。第一层，算法规范：块结构、统计量合并、掩码与接口写成文档与参考实现（FP32 逐块参考），这是所有后端共享的合同。第二层，调度实现：每后端按自身原语重排——A100 用异步拷贝双缓冲，Hopper 用 TMA 加 warp 特化（<a href="/llm/flashattention-3">FlashAttention-3</a> 的口径），Triton 让编译器生成（<a href="/llm/triton-attention-kernel">Triton 写注意力核</a>），成熟厂商库（<a href="/llm/flashinfer">FlashInfer 内核库</a>、cuDNN）直接接管整段。第三层，路由：前端按硬件能力、形状桶与后端可用性查表选路，未命中回退到保底实现。每个后端过同一套基准网格与数值验收，报告按后端分列，倍数不跨卡平移。</p><p><span class="marginnote">直觉类比：三层移植像连锁餐厅——菜谱（算法规范）全城统一，每家分店（后端）用自己的灶具做出同样的火候，前台排班（路由）按客人点了什么、哪家店开着来分单，最后每家店过同一套出品检查（验收）。菜的味道不许变，灶怎么用各店自便。</span></p>',3)),(A(),l(i,null,{default:E(()=>[r(t,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E7%AE%97%E6%B3%95%E8%A7%84%E8%8C%83%EF%BC%9A%E5%9D%97%E7%BB%93%E6%9E%84%2B%E5%9C%A8%E7%BA%BF%20softmax%2B%E6%8E%A5%E5%8F%A3%22%5D%20--%3E%20B%5B%22%E6%95%B0%E5%80%BC%E9%AA%8C%E6%94%B6%E5%90%88%E5%90%8C%EF%BC%9A%E7%BB%9F%E4%B8%80%E5%8F%82%E8%80%83%2B%E5%88%86%E6%A1%A3%E5%AE%B9%E5%B7%AE%22%5D%0A%20%20B%20--%3E%20C%7B%22%E8%B7%AF%E7%94%B1%EF%BC%9A%E7%A1%AC%E4%BB%B6%E8%83%BD%E5%8A%9B%E4%B8%8E%E5%BD%A2%E7%8A%B6%22%7D%0A%20%20C%20--%3E%20D%5B%22%E6%89%8B%E5%86%99%E5%90%8E%E7%AB%AF%EF%BC%9ACUDA%20%2F%20CUTLASS%22%5D%0A%20%20C%20--%3E%20E%5B%22Triton%20%E5%90%8E%E7%AB%AF%22%5D%0A%20%20C%20--%3E%20F%5B%22%E5%8E%82%E5%95%86%E5%BA%93%E5%90%8E%E7%AB%AF%22%5D%0A%20%20D%20--%3E%20G%5B%22%E5%90%84%E8%87%AA%E8%BF%87%E5%9F%BA%E5%87%86%E7%BD%91%E6%A0%BC%E4%B8%8E%E9%AA%8C%E6%94%B6%22%5D%0A%20%20E%20--%3E%20G%0A%20%20F%20--%3E%20G%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[B(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=e('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>为什么验收必须跨后端同一口径：数值差异主要来自归约顺序与累加宽度，这些是合法差异；但合法差异必须可见才能与真 bug 区分。统一参考加每后端分档容差，漂移就从「玄学」变成「表里的一项」。为什么算法层要先钉死：移植中最贵的错误是每家对算法的理解略有不同——之后每个 bug 要修 N 份，而且修的顺序互相踩。错法从最快后端反向理解算法：把它的调度技巧当成数学的一部分，换到没有该原语的硬件上就写出错的「等价物」。还有一个静默坑：某后端不支持某条量化或稀疏路径时，路由若静默换成别的路径，用户拿到的数值与延迟都变了却不知情——正确做法是显式降级并在响应元数据里标注。</p><p><span class="marginnote">同一份 FlashAttention 的相对加速不可跨卡平移：Hopper 的收益来自 TMA 与 warp 特化，A100 没有这些原语，AMD 的矩阵指令形状又不同。对外只承诺「接口一致、各自验收达标」，不承诺倍数一致——承诺倍数的移植文档，第一页就错了。</span></p><p><span class="marginnote">为什么重要：路由静默换路径时，用户拿到的数值和延迟都变了却毫不知情，日后两边一对照还对不上账。正确做法是把「这次没走最优后端」显式写进响应元数据——就像航班换了机型要在票面上注明，而不是偷偷换一架。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>移植不改语义：任何后端都不该为了性能改掩码、改精度路径、改归并结构，除非改动能通过同一份验收并写进差异表。性能可移植性（一份代码到处快）是编译器研究的题目，本课做的是工程可移植：分层、路由、验收。新硬件到手，第一件事是重跑第 3 课的预算表——smem、寄存器、矩阵原子全是新数，旧 tile 直接搬过去等于没移植。预算、基准、调优、移植四课连起来，才是内核工程的完整交付链。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>移植分三层：算法规范共享、调度实现各自重排、路由按能力与形状查表。</li><li>数值验收用统一参考加分档容差，让合法漂移可见、真 bug 无处藏。</li><li>别把最快后端的调度技巧当数学：从原语反推算法是移植的第一错误源。</li><li>后端能力缺失要显式降级并标注，不静默换路径。</li><li>新硬件先重跑预算表，再谈移植；倍数不跨卡承诺。</li><li>出处：据 NVIDIA CUTLASS 与 FlashInfer 文档、Tillet et al., <em>Triton</em>, MAPL 2019 整理。</li></ul>',8))])}const u=n(p,[["render",m]]);export{_ as __pageData,u as default};
